41	type h2ReadWriteCloser struct {
42		io.ReadCloser
43		http.ResponseWriter
44	}
45	
46	func (rwc h2ReadWriteCloser) Write(p []byte) (n int, err error) {
47		n, err = rwc.ResponseWriter.Write(p)
48		if err != nil {
49			return 0, err
50		}
51	
52		//nolint:bodyclose
53		err = http.NewResponseController(rwc.ResponseWriter).Flush()
54		if err != nil {
55			return 0, err
56		}
57		return n, nil
58	}
59	
60	func (h *Handler) handleUpgradeResponse(logger *zap.Logger, wg *sync.WaitGroup, rw http.ResponseWriter, req *http.Request, res *http.Response) {
61		reqUpType := upgradeType(req.Header)
62		resUpType := upgradeType(res.Header)
63	
64		// Taken from https://github.com/golang/go/commit/5c489514bc5e61ad9b5b07bd7d8ec65d66a0512a
65		// We know reqUpType is ASCII, it's checked by the caller.
66		if !asciiIsPrint(resUpType) {
67			if c := logger.Check(zapcore.DebugLevel, "backend tried to switch to invalid protocol"); c != nil {
68				c.Write(zap.String("backend_upgrade", resUpType))
69			}
70			return
71		}
72		if !asciiEqualFold(reqUpType, resUpType) {
73			if c := logger.Check(zapcore.DebugLevel, "backend tried to switch to unexpected protocol via Upgrade header"); c != nil {
74				c.Write(
75					zap.String("backend_upgrade", resUpType),
76					zap.String("requested_upgrade", reqUpType),
77				)
78			}
79			return
80		}
81	
82		backConn, ok := res.Body.(io.ReadWriteCloser)
83		if !ok {
84			logger.Error("internal error: 101 switching protocols response with non-writable body")
85			return
86		}
87	
88		// write header first, response headers should not be counted in size
89		// like the rest of handler chain.
90		copyHeader(rw.Header(), res.Header)
91		normalizeWebsocketHeaders(rw.Header())
92	
93		var (
94			conn io.ReadWriteCloser
95			brw  *bufio.ReadWriter
96		)
97		// websocket over http2 or http3 if extended connect is enabled, assuming backend doesn't support this, the request will be modified to http1.1 upgrade
98		// TODO: once we can reliably detect backend support this, it can be removed for those backends
99		if body, ok := caddyhttp.GetVar(req.Context(), "extended_connect_websocket_body").(io.ReadCloser); ok {
100			req.Body = body
101			rw.Header().Del("Upgrade")
102			rw.Header().Del("Connection")
103			delete(rw.Header(), "Sec-WebSocket-Accept")
104			rw.WriteHeader(http.StatusOK)
105	
106			if c := logger.Check(zap.DebugLevel, "upgrading connection"); c != nil {
107				c.Write(zap.Int("http_version", 2))
108			}
109	
110			//nolint:bodyclose
111			flushErr := http.NewResponseController(rw).Flush()
112			if flushErr != nil {
113				if c := h.logger.Check(zap.ErrorLevel, "failed to flush http2 websocket response"); c != nil {
114					c.Write(zap.Error(flushErr))
115				}
116				return
117			}
118			conn = h2ReadWriteCloser{req.Body, rw}
119			// bufio is not needed, use minimal buffer
120			brw = bufio.NewReadWriter(bufio.NewReaderSize(conn, 1), bufio.NewWriterSize(conn, 1))
121		} else {
122			rw.WriteHeader(res.StatusCode)
123	
124			if c := logger.Check(zap.DebugLevel, "upgrading connection"); c != nil {
125				c.Write(zap.Int("http_version", req.ProtoMajor))
126			}
127	
128			var hijackErr error
129			//nolint:bodyclose
130			conn, brw, hijackErr = http.NewResponseController(rw).Hijack()
131			if errors.Is(hijackErr, http.ErrNotSupported) {
132				if c := h.logger.Check(zap.ErrorLevel, "can't switch protocols using non-Hijacker ResponseWriter"); c != nil {
133					c.Write(zap.String("type", fmt.Sprintf("%T", rw)))
134				}
135				return
136			}
137	
138			if hijackErr != nil {
139				if c := h.logger.Check(zap.ErrorLevel, "hijack failed on protocol switch"); c != nil {
140					c.Write(zap.Error(hijackErr))
141				}
142				return
143			}
144		}
145	
146		// adopted from https://github.com/golang/go/commit/8bcf2834afdf6a1f7937390903a41518715ef6f5
147		backConnCloseCh := make(chan struct{})
148		go func() {
149			// Ensure that the cancellation of a request closes the backend.
150			// See issue https://golang.org/issue/35559.
151			select {
152			case <-req.Context().Done():
153			case <-backConnCloseCh:
154			}
155			backConn.Close()
156		}()
157		defer close(backConnCloseCh)
158	
159		start := time.Now()
160		defer func() {
161			conn.Close()
162			if c := logger.Check(zapcore.DebugLevel, "connection closed"); c != nil {
163				c.Write(zap.Duration("duration", time.Since(start)))
164			}
165		}()
166	
167		if err := brw.Flush(); err != nil {
168			if c := logger.Check(zapcore.DebugLevel, "response flush"); c != nil {
169				c.Write(zap.Error(err))
170			}
171			return
172		}
173	
174		// There may be buffered data in the *bufio.Reader
175		// see: https://github.com/caddyserver/caddy/issues/6273
176		if buffered := brw.Reader.Buffered(); buffered > 0 {
177			data, _ := brw.Peek(buffered)
178			_, err := backConn.Write(data)
179			if err != nil {
180				if c := logger.Check(zapcore.DebugLevel, "backConn write failed"); c != nil {
181					c.Write(zap.Error(err))
182				}
183				return
184			}
185		}
186	
187		// Ensure the hijacked client connection, and the new connection established
188		// with the backend, are both closed in the event of a server shutdown. This
189		// is done by registering them. We also try to gracefully close connections
190		// we recognize as websockets.
191		// We need to make sure the client connection messages (i.e. to upstream)
192		// are masked, so we need to know whether the connection is considered the
193		// server or the client side of the proxy.
194		gracefulClose := func(conn io.ReadWriteCloser, isClient bool) func() error {
195			if isWebsocket(req) {
196				return func() error {
197					return writeCloseControl(conn, isClient)
198				}
199			}
200			return nil
201		}
202		deleteFrontConn := h.registerConnection(conn, gracefulClose(conn, false))
203		deleteBackConn := h.registerConnection(backConn, gracefulClose(backConn, true))
204		defer deleteFrontConn()
205		defer deleteBackConn()
206	
207		spc := switchProtocolCopier{
208			user:       conn,
209			backend:    backConn,
210			wg:         wg,
211			bufferSize: h.StreamBufferSize,
212		}
213	
214		// setup the timeout if requested
215		var timeoutc <-chan time.Time
216		if h.StreamTimeout > 0 {
217			timer := time.NewTimer(time.Duration(h.StreamTimeout))
218			defer timer.Stop()
219			timeoutc = timer.C
220		}
221	
222		// when a stream timeout is encountered, no error will be read from errc
223		// a buffer size of 2 will allow both the read and write goroutines to send the error and exit
224		// see: https://github.com/caddyserver/caddy/issues/7418
225		errc := make(chan error, 2)
226		wg.Add(2)
227		go spc.copyToBackend(errc)
228		go spc.copyFromBackend(errc)
229	
230		// Wait for both directions to finish. A clean EOF in one direction is a
231		// half-close of that direction only, not the end of the tunnel: the copier
232		// propagates it to the destination with CloseWrite and reports nil, so the
233		// other direction is left open and pending bytes can still drain. Anything
234		// else ends the tunnel: a copy error, a failed CloseWrite, or errCopyDone
235		// when the destination has no write half to close.
236		//
237		// net/http/httputil expresses the same wait as:
238		//
239		//	err := <-errc
240		//	if err == nil {
241		//		err = <-errc
242		//	}
243		//
244		// which cannot be used verbatim here because this handler also selects on the
245		// stream timeout, so the wait is repeated inside that select instead. Both
246		// accept the same sequences; the loop only additionally lets the timeout win
247		// at either wait.
248		//
249		// See https://github.com/caddyserver/caddy/issues/8026, and the same class
250		// fixed upstream in net/http/httputil (https://go.dev/issue/35892).
251		for range 2 {
252			select {
253			case err := <-errc:
254				if err != nil {
255					if c := logger.Check(zapcore.DebugLevel, "streaming error"); c != nil {
256						c.Write(zap.Error(err))
257					}
258					return
259				}
260			case time := <-timeoutc:
261				if c := logger.Check(zapcore.DebugLevel, "stream timed out"); c != nil {
262					c.Write(zap.Time("timeout", time))
263				}
264				return
265			}
266		}
267	}
268	
269	// flushInterval returns the p.FlushInterval value, conditionally
270	// overriding its value for a specific request/response.
271	func (h Handler) flushInterval(req *http.Request, res *http.Response, incremental bool) time.Duration {
272		// The upstream asked for the response to be forwarded incrementally.
273		// See RFC 10036: https://www.rfc-editor.org/rfc/rfc10036.html
274		if incremental || caddyhttp.IsIncremental(res.Header) {
275			return -1 // negative means immediately
276		}
277	
278		resCTHeader := res.Header.Get("Content-Type")
279		resCT, _, err := mime.ParseMediaType(resCTHeader)
280	
281		// For Server-Sent Events responses, flush immediately.
282		// The MIME type is defined in https://www.w3.org/TR/eventsource/#text-event-stream
283		if err == nil && resCT == "text/event-stream" {
284			return -1
285		}
286	
287		// We might have the case of streaming for which Content-Length might be unset.
288		if res.ContentLength == -1 {
289			return -1
290		}
291	
292		// for h2 and h2c upstream streaming data to client (issues #3556 and #3606)
293		if h.isBidirectionalStream(req, res) {
294			return -1
295		}
296	
297		return time.Duration(h.FlushInterval)
298	}
299	
300	// isBidirectionalStream returns whether we should work in bi-directional stream mode.
301	//
302	// See https://github.com/caddyserver/caddy/pull/3620 for discussion of nuances.
303	func (h Handler) isBidirectionalStream(req *http.Request, res *http.Response) bool {
304		// We have to check the encoding here; only flush headers with identity encoding.
305		// Non-identity encoding might combine with "encode" directive, and in that case,
306		// if body size larger than enc.MinLength, upper level encode handle might have
307		// Content-Encoding header to write.
308		// (see https://github.com/caddyserver/caddy/issues/3606 for use case)
309		ae := req.Header.Get("Accept-Encoding")
310	
311		return req.ProtoMajor == 2 &&
312			res.ProtoMajor == 2 &&
313			res.ContentLength == -1 &&
314			(ae == "identity" || ae == "")
315	}
316	
317	func (h Handler) copyResponse(dst http.ResponseWriter, src io.Reader, flushInterval time.Duration, logger *zap.Logger) error {
318		var w io.Writer = dst
319	
320		if flushInterval != 0 {
321			var mlwLogger *zap.Logger
322			if h.VerboseLogs {
323				mlwLogger = logger.Named("max_latency_writer")
324			} else {
325				mlwLogger = zap.NewNop()
326			}
327			mlw := &maxLatencyWriter{
328				dst: dst,
329				//nolint:bodyclose
330				flush:   http.NewResponseController(dst).Flush,
331				latency: flushInterval,
332				logger:  mlwLogger,
333			}
334			defer mlw.stop()
335	
336			// set up initial timer so headers get flushed even if body writes are delayed
337			mlw.flushPending = true
338			mlw.t = time.AfterFunc(flushInterval, mlw.delayedFlush)
339	
340			w = mlw
341		}
342	
343		buf := streamingBufPool.Get().(*[]byte)
344		defer streamingBufPool.Put(buf)
345	
346		var copyLogger *zap.Logger
347		if h.VerboseLogs {
348			copyLogger = logger
349		} else {
350			copyLogger = zap.NewNop()
351		}
352	
353		_, err := h.copyBuffer(w, src, *buf, copyLogger)
354		return err
355	}
356	
357	// copyBuffer returns any write errors or non-EOF read errors, and the amount
358	// of bytes written.
359	func (h Handler) copyBuffer(dst io.Writer, src io.Reader, buf []byte, logger *zap.Logger) (int64, error) {
360		if len(buf) == 0 {
361			buf = make([]byte, defaultBufferSize)
362		}
363		var written int64
364		for {
365			logger.Debug("waiting to read from upstream")
366			nr, rerr := src.Read(buf)
367			logger := logger.With(zap.Int("read", nr))
368			if c := logger.Check(zapcore.DebugLevel, "read from upstream"); c != nil {
369				c.Write(zap.Error(rerr))
370			}
371			if rerr != nil && rerr != io.EOF && rerr != context.Canceled {
372				// TODO: this could be useful to know (indeed, it revealed an error in our
373				// fastcgi PoC earlier; but it's this single error report here that necessitates
374				// a function separate from io.CopyBuffer, since io.CopyBuffer does not distinguish
375				// between read or write errors; in a reverse proxy situation, write errors are not
376				// something we need to report to the client, but read errors are a problem on our
377				// end for sure. so we need to decide what we want.)
378				// p.logf("copyBuffer: ReverseProxy read error during body copy: %v", rerr)
379				if c := logger.Check(zapcore.ErrorLevel, "reading from backend"); c != nil {
380					c.Write(zap.Error(rerr))
381				}
382			}
383			if nr > 0 {
384				logger.Debug("writing to downstream")
385				nw, werr := dst.Write(buf[:nr])
386				if nw > 0 {
387					written += int64(nw)
388				}
389				if c := logger.Check(zapcore.DebugLevel, "wrote to downstream"); c != nil {
390					c.Write(
391						zap.Int("written", nw),
392						zap.Int64("written_total", written),
393						zap.Error(werr),
394					)
395				}
396				if werr != nil {
397					return written, fmt.Errorf("writing: %w", werr)
398				}
399				if nr != nw {
400					return written, io.ErrShortWrite
401				}
402			}
403			if rerr != nil {
404				if rerr == io.EOF {
405					return written, nil
406				}
407				return written, fmt.Errorf("reading: %w", rerr)
408			}
409		}
410	}
411	
412	// registerConnection holds onto conn so it can be closed in the event
413	// of a server shutdown. This is useful because hijacked connections or
414	// connections dialed to backends don't close when server is shut down.
415	// The caller should call the returned delete() function when the
416	// connection is done to remove it from memory.
417	func (h *Handler) registerConnection(conn io.ReadWriteCloser, gracefulClose func() error) (del func()) {
418		h.connectionsMu.Lock()
419		h.connections[conn] = openConnection{conn, gracefulClose}
420		h.connectionsMu.Unlock()
421		return func() {
422			h.connectionsMu.Lock()
423			delete(h.connections, conn)
424			// if there is no connection left before the connections close timer fires
425			if len(h.connections) == 0 && h.connectionsCloseTimer != nil {
426				// we release the timer that holds the reference to Handler
427				if (*h.connectionsCloseTimer).Stop() {
428					h.logger.Debug("stopped streaming connections close timer - all connections are already closed")
429				}
430				h.connectionsCloseTimer = nil
431			}
432			h.connectionsMu.Unlock()
433		}
434	}
435	
436	// closeConnections immediately closes all hijacked connections (both to client and backend).
437	func (h *Handler) closeConnections() error {
438		var err error
439		h.connectionsMu.Lock()
440		defer h.connectionsMu.Unlock()
441	
442		for _, oc := range h.connections {
443			if oc.gracefulClose != nil {
444				// this is potentially blocking while we have the lock on the connections
445				// map, but that should be OK since the server has in theory shut down
446				// and we are no longer using the connections map
447				gracefulErr := oc.gracefulClose()
448				if gracefulErr != nil && err == nil {
449					err = gracefulErr
450				}
451			}
452			closeErr := oc.conn.Close()
453			if closeErr != nil && err == nil {
454				err = closeErr
455			}
456		}
457		return err
458	}
459	
460	// cleanupConnections closes hijacked connections.
461	// Depending on the value of StreamCloseDelay it does that either immediately
462	// or sets up a timer that will do that later.
463	func (h *Handler) cleanupConnections() error {
464		if h.StreamCloseDelay == 0 {
465			return h.closeConnections()
466		}
467	
468		h.connectionsMu.Lock()
469		defer h.connectionsMu.Unlock()
470		// the handler is shut down, no new connection can appear,
471		// so we can skip setting up the timer when there are no connections
472		if len(h.connections) > 0 {
473			delay := time.Duration(h.StreamCloseDelay)
474			h.connectionsCloseTimer = time.AfterFunc(delay, func() {
475				if c := h.logger.Check(zapcore.DebugLevel, "closing streaming connections after delay"); c != nil {
476					c.Write(zap.Duration("delay", delay))
477				}
478				err := h.closeConnections()
479				if err != nil {
480					if c := h.logger.Check(zapcore.ErrorLevel, "failed to closed connections after delay"); c != nil {
481						c.Write(
482							zap.Error(err),
483							zap.Duration("delay", delay),
484						)
485					}
486				}
487			})
488		}
489		return nil
490	}
491	
492	// writeCloseControl sends a best-effort Close control message to the given
493	// WebSocket connection. Thanks to @pascaldekloe who provided inspiration
494	// from his simple implementation of this I was able to learn from at:
495	// github.com/pascaldekloe/websocket. Further work for handling masking
496	// taken from github.com/gorilla/websocket.
497	func writeCloseControl(conn io.Writer, isClient bool) error {
498		// Sources:
499		// https://github.com/pascaldekloe/websocket/blob/32050af67a5d/websocket.go#L119
500		// https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L413
501	
502		// For now, we're not using a reason. We might later, though.
503		// The code handling the reason is left in
504		var reason string // max 123 bytes (control frame payload limit is 125; status code takes 2)
505	
506		const closeMessage = 8
507		const finalBit = 1 << 7 // Frame header byte 0 bits from Section 5.2 of RFC 6455
508		const maskBit = 1 << 7  // Frame header byte 1 bits from Section 5.2 of RFC 6455
509		const goingAwayUpper uint8 = 1001 >> 8

